def parse_args():
    parser = argparse.ArgumentParser(
        description=\"Make your i3 config a bit more stylish\",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=\"\"\"
Example:
    i3-style solarized -o ~/.config/i3/config --reload
    i3-style ~/.config/i3/solarized.yaml -o ~/.config/i3/config
    i3-style --to-theme ~/.config/i3/config -o my-theme.yaml
\"\"\"
    )
    parser.add_argument(\"-h\", \"--help\", action=\"store_true\", help=\"Prints help information\")
    parser.add_argument(\"-l\", \"--list-all\", action=\"store_true\", help=\"Print a list of all available themes\")
    parser.add_argument(\"-r\", \"--reload\", action=\"store_true\", help=\"Apply the theme by reloading the config\")
    parser.add_argument(\"-s\", \"--save\", action=\"store_true\", help=\"Set the output file to the path of the input file\")
    parser.add_argument(\"-V\", \"--version\", action=\"store_true\", help=\"Prints version information\")
    parser.add_argument(\"-c\", \"--config\", metavar=\"file\", help=\"The config file the theme should be applied to. Defaults to the default i3 location.\")
    parser.add_argument(\"-o\", \"--output\", metavar=\"file\", help=\"Apply the theme, attempt to validate the result, and write it to <file>\")
    parser.add_argument(\"-t\", \"--to-theme\", metavar=\"file\", help=\"Prints an i3-style theme based on the given config suitable for sharing with others\")
    parser.add_argument(\"theme\", nargs=\"?\", help=\"The theme to use\")
    return parser.parse_args()

def load_theme(theme_name):
    if theme_name in BUILTIN_THEMES:
        return BUILTIN_THEMES[theme_name]
    if os.path.isfile(theme_name):
        with open(theme_name, \"r\") as f:
            return yaml.safe_load(f)
    raise ValueError(f\"Unknown theme: {theme_name}\")

def get_color_value(color_name, theme):
    if \"colors\" in theme and color_name in theme[\"colors\"]:
        return theme[\"colors\"][color_name]
    return None

def get_window_color(theme, window_type, color_name):
    if \"window_colors\" in theme and window_type in theme[\"window_colors\"]:
        window_colors = theme[\"window_colors\"][window_type]
        if color_name in window_colors:
            return window_colors[color_name]
    return None

def get_bar_color(theme, color_name):
    if \"bar_colors\" in theme and color_name in theme[\"bar_colors\"]:
        return theme[\"bar_colors\"][color_name]
    return None

def apply_theme_to_config(config_content, theme, config_path):
    lines = config_content.split(\"\\n\")
    result_lines = []
    in_bar = False
    in_bar_colors = False

    for line in lines:
        stripped = line.strip()

        if stripped == \"bar {\":
            in_bar = True
            result_lines.append(line)
            continue

        if stripped == \"}\":
            in_bar = False
            result_lines.append(line)
            continue

        if in_bar and stripped.startswith(\"colors {\"):
            in_bar_colors = True
            result_lines.append(line)
            continue

        if in_bar and stripped == \"}\":
            in_bar_colors = False
            result_lines.append(line)
            continue

        if stripped.startswith(\"client.\"):
            client_type = stripped.split()[0]
            colors = get_window_color(theme, client_type, \"background\")
            if colors:
                result_lines.append(f\"{client_type} {colors}\")
                continue

        if in_bar_colors:
            if stripped.startswith(\"separator\"):
                color = get_bar_color(theme, \"separator\")
                if color:
                    result_lines.append(f\"  colors {{\\n    separator {color}\")
                    continue
            elif stripped.startswith(\"background\"):
                color = get_bar_color(theme, \"background\")
                if color:
                    result_lines.append(f\"  colors {{\\n    background {color}\")
                    continue
            elif stripped.startswith(\"statusline\"):
                color = get_bar_color(theme, \"statusline\")
                if color:
                    result_lines.append(f\"  colors {{\\n    statusline {color}\")
                    continue
            elif stripped.startswith(\"focused_workspace\"):
                colors = get_window_color(theme, \"focused_workspace\", \"background\")
                if colors:
                    result_lines.append(f\"  colors {{\\n    focused_workspace {colors}\")
                    continue
            elif stripped.startswith(\"active_workspace\"):
                colors = get_window_color(theme, \"active_workspace\", \"background\")
                if colors:
                    result_lines.append(f\"  colors {{\\n    active_workspace {colors}\")
                    continue
            elif stripped.startswith(\"inactive_workspace\"):
                colors = get_window_color(theme, \"inactive_workspace\", \"background\")
                if colors:
                    result_lines.append(f\"  colors {{\\n    inactive_workspace {colors}\")
                    continue
            elif stripped.startswith(\"urgent_workspace\"):
                colors = get_window_color(theme, \"urgent_workspace\", \"background\")
                if colors:
                    result_lines.append(f\"  colors {{\\n    urgent_workspace {colors}\")
                    continue

        result_lines.append(line)

    return \"\\n\".join(result_lines)

def validate_config(config_path):
    try:
        result = subprocess.run(
            [\"i3\", \"-C\", \"-c\", config_path],
            capture_output=True,
            text=True,
            timeout=10
        )
        return result.returncode == 0
    except FileNotFoundError:
        return False
    except subprocess.TimeoutExpired:
        return False

def main():
    args = parse_args()

    if args.version:
        print(f\"i3-style {VERSION}\")
        return 0

    if args.help:
        print(\"i3-style 1.0\")
        print(\"Make your i3 config a bit more stylish\")
        print()
        print(\"USAGE:\")
        print(\"    executable [FLAGS] [OPTIONS] [theme]\")
        print()
        print(\"FLAGS:\")
        print(\"    -h, --help        Prints help information\")
        print(\"    -l, --list-all    Print a list of all available themes\")
        print(\"    -r, --reload      Apply the theme by reloading the config\")
        print(\"    -s, --save        Set the output file to the path of the input file\")
        print(\"    -V, --version     Prints version information\")
        print()
        print(\"OPTIONS:\")
        print(\"    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.\")
        print(\"    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>\")
        print(\"    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others\")
        print(\"                             [default: ]\")
        print()
        print(\"ARGS:\")
        print(\"    <theme>    The theme to use\")
        return 0

    if args.list_all:
        print(\"\\nAvailable themes:\")
        print()
        for name in sorted(BUILTIN_THEMES.keys()):
            theme = BUILTIN_THEMES[name]
            desc = theme.get(\"meta\", {}).get(\"description\", \"No description\")
            print(f\"  {name:20} - {desc}\")
        return 0

    try:
        theme = load_theme(args.theme)
    except ValueError as e:
        print(str(e), file=sys.stderr)
        return 1

    config_path = args.config or DEFAULT_CONFIG
    output_path = args.output
    if not output_path:
        if args.save:
            output_path = config_path
        else:
            output_path = DEFAULT_CONFIG

    if args.to_theme:
        try:
            with open(args.to_theme, \"r\") as f:
                config_content = f.read()
        except FileNotFoundError:
            print(f\"Config file not found: {args.to_theme}\", file=sys.stderr)
            return 1

        colors = {}
        window_colors = {}
        bar_colors = {}

        color_pattern = r\"#([0-9A-Fa-f]{6})\"

        for client_type in [\"focused\", \"focused_inactive\", \"unfocused\", \"urgent\"]:
            match = re.search(rf\"client\\.{client_type}\\s+{color_pattern}\\s+{color_pattern}\\s+{color_pattern}\\s+{color_pattern}\", config_content)
            if match:
                colors[client_type] = match.group(0).split()[-4:]

        bar_match = re.search(r\"bar\\s*\\{[^}]*colors\\s*\\{([^}]+)\\}\", config_content, re.DOTALL)
        if bar_match:
            bar_colors_section = bar_match.group(1)
            for prop in [\"separator\", \"background\", \"statusline\", \"focused_workspace\", \"active_workspace\", \"inactive_workspace\", \"urgent_workspace\"]:
                prop_match = re.search(rf\"{prop}\\s+{color_pattern}\", bar_colors_section)
                if prop_match:
                    bar_colors[prop] = prop_match.group(1)

        theme = {
            \"meta\": {\"description\": \"Generated theme\"},
            \"colors\": {},
            \"window_colors\": {
                \"focused\": {\"border\": colors.get(\"focused\", \"#664477\"), \"background\": colors.get(\"focused\", \"#664477\"), \"text\": colors.get(\"focused\", \"#e7d8b1\"), \"indicator\": colors.get(\"focused\", \"#DCCD69\")},
                \"focused_inactive\": {\"border\": colors.get(\"focused_inactive\", \"#181715\"), \"background\": colors.get(\"focused_inactive\", \"#181715\"), \"text\": colors.get(\"focused_inactive\", \"#e7d8b1\"), \"indicator\": colors.get(\"focused_inactive\", \"#DCCD69\")},
                \"unfocused\": {\"border\": colors.get(\"unfocused\", \"#181715\"), \"background\": colors.get(\"unfocused\", \"#181715\"), \"text\": colors.get(\"unfocused\", \"#cccccc\"), \"indicator\": colors.get(\"unfocused\", \"#A074C4\")},
                \"urgent\": {\"border\": colors.get(\"urgent\", \"#CE4045\"), \"background\": colors.get(\"urgent\", \"#CE4045\"), \"text\": colors.get(\"urgent\", \"#e7d8b1\"), \"indicator\": colors.get(\"urgent\", \"#DC322F\")},
            },
            \"bar_colors\": {
                \"background\": bar_colors.get(\"background\", \"#222133\"),
                \"statusline\": bar_colors.get(\"statusline\", \"#FFFFFF\"),
                \"separator\": bar_colors.get(\"separator\", \"#AAAAAA\"),
                \"focused_workspace\": {\"border\": bar_colors.get(\"focused_workspace\", \"#e7d8b1\"), \"background\": bar_colors.get(\"focused_workspace\", \"#664477\"), \"text\": bar_colors.get(\"focused_workspace\", \"#e7d8b1\")},
                \"urgent_workspace\": {\"border\": bar_colors.get(\"urgent_workspace\", \"#CE4045\"), \"background\": bar_colors.get(\"urgent_workspace\", \"#CE4045\"), \"text\": bar_colors.get(\"urgent_workspace\", \"#e7d8b1\")},
            },
        }

        print(yaml.dump(theme, default_flow_style=False))
        return 0

    try:
        with open(config_path, \"r\") as f:
            config_content = f.read()
    except FileNotFoundError:
        print(f\"Config file not found: {config_path}\", file=sys.stderr)
        return 1

    result_content = apply_theme_to_config(config_content, theme, config_path)

    if args.output:
        if not validate_config(args.output):
            print(f\"Could not validate config with `i3 -C -c {args.output}` (is i3 in the PATH?)\", file=sys.stderr)
